if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
 if($action==='event-save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$starts=(string)($_POST['starts_at']??'');$status=(string)($_POST['status']??'draft');$u=(int)($_POST['unit_id']??0);if($name===''||$starts===''||!in_array($status,['draft','published','closed','cancelled'],true))throw new RuntimeException('Evento inválido.');$slug=em_slug((string)($_POST['slug']??$name));$ends=(string)($_POST['ends_at']??'');$starts=str_replace('T',' ',$starts);$ends=$ends?str_replace('T',' ',$ends):null;if($id){$s=$pdo->prepare('UPDATE events SET unit_id=?,name=?,slug=?,description=?,venue=?,address=?,starts_at=?,ends_at=?,status=?,banner_url=? WHERE id=? AND tenant_id=?');$s->execute([$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null,$id,$tenantId]);}else{$s=$pdo->prepare('INSERT INTO events (tenant_id,unit_id,name,slug,description,venue,address,starts_at,ends_at,status,banner_url) VALUES (?,?,?,?,?,?,?,?,?,?,?)');try{$s->execute([$tenantId,$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null]);}catch(PDOException){$slug.='-'.substr(bin2hex(random_bytes(3)),0,5);$s->execute([$tenantId,$u?:null,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null]);}$id=(int)$pdo->lastInsertId();}Auth::audit('event.saved','event',(string)$id);em_flash('ok','Evento salvo.');em_go('events',['edit'=>$id]);}
 if($action==='batch-save'){$eventId=(int)($_POST['event_id']??0);$id=(int)($_POST['id']??0);$e=$pdo->prepare('SELECT id FROM events WHERE id=? AND tenant_id=?');$e->execute([$eventId,$tenantId]);if(!$e->fetchColumn())throw new RuntimeException('Evento inválido.');$name=trim((string)($_POST['name']??''));$price=(int)round((float)str_replace(',','.',(string)($_POST['price']??'0'))*100);$qty=max(1,(int)($_POST['quantity_total']??1));$start=(string)($_POST['sales_start']??'');$end=(string)($_POST['sales_end']??'');$start=$start?str_replace('T',' ',$start):null;$end=$end?str_replace('T',' ',$end):null;if($name===''||$price<0)throw new RuntimeException('Lote inválido.');if($id){$lock=$pdo->prepare('SELECT quantity_sold,quantity_reserved FROM ticket_batches WHERE id=? AND event_id=? FOR UPDATE');$lock->execute([$id,$eventId]);$old=$lock->fetch();if(!$old)throw new RuntimeException('Lote não encontrado.');if($qty<(int)$old['quantity_sold']+(int)$old['quantity_reserved'])throw new RuntimeException('Quantidade total não pode ser menor que vendidos + reservados.');$pdo->prepare('UPDATE ticket_batches SET name=?,price_cents=?,quantity_total=?,sales_start=?,sales_end=?,active=? WHERE id=? AND event_id=?')->execute([$name,$price,$qty,$start,$end,isset($_POST['active'])?1:0,$id,$eventId]);}else{$pdo->prepare('INSERT INTO ticket_batches (event_id,name,price_cents,quantity_total,sales_start,sales_end,active) VALUES (?,?,?,?,?,?,1)')->execute([$eventId,$name,$price,$qty,$start,$end]);$id=(int)$pdo->lastInsertId();}Auth::audit('ticket_batch.saved','ticket_batch',(string)$id);em_flash('ok','Lote salvo.');em_go('events',['edit'=>$eventId]);}
 if($action==='duplicate'){Database::transaction(function(PDO$db)use($tenantId){$id=(int)$_POST['id'];$s=$db->prepare('SELECT * FROM events WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$id,$tenantId]);$event=$s->fetch();if(!$event)throw new RuntimeException('Evento não encontrado.');$slug=em_slug($event['slug'].'-copia-'.substr(bin2hex(random_bytes(2)),0,4));$db->prepare('INSERT INTO events (tenant_id,unit_id,name,slug,description,venue,address,starts_at,ends_at,status,banner_url) VALUES (?,?,?,?,?,?,?,?,?,"draft",?)')->execute([$tenantId,$event['unit_id'],$event['name'].' (cópia)',$slug,$event['description'],$event['venue'],$event['address'],$event['starts_at'],$event['ends_at'],$event['banner_url']]);$new=(int)$db->lastInsertId();$b=$db->prepare('SELECT * FROM ticket_batches WHERE event_id=? ORDER BY id');$b->execute([$id]);$ins=$db->prepare('INSERT INTO ticket_batches (event_id,name,price_cents,quantity_total,quantity_sold,quantity_reserved,sales_start,sales_end,active) VALUES (?,?,?, ?,0,0,?,?,?)');foreach($b->fetchAll()as$row)$ins->execute([$new,$row['name'],$row['price_cents'],$row['quantity_total'],$row['sales_start'],$row['sales_end'],$row['active']]);Auth::audit('event.duplicated','event',(string)$new,['source'=>$id]);});em_flash('ok','Evento duplicado como rascunho.');em_go('events');}
 if($action==='delete'){$id=(int)$_POST['id'];Database::transaction(function(PDO$db)use($tenantId,$id){$s=$db->prepare('SELECT id FROM events WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$id,$tenantId]);if(!$s->fetch())throw new RuntimeException('Evento não encontrado.');$c=$db->prepare('SELECT COUNT(*) FROM tickets WHERE event_id=?');$c->execute([$id]);if((int)$c->fetchColumn()>0){$db->prepare('UPDATE events SET status="cancelled" WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);Auth::audit('event.archived','event',(string)$id);}else{$db->prepare('DELETE FROM events WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);Auth::audit('event.deleted','event',(string)$id);}});em_flash('ok','Evento atualizado.');em_go('events');}
}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('events');}}
$editId=(int)($_GET['edit']??0);$isNew=isset($_GET['new']);$edit=null;$batches=[];if($editId){$s=$pdo->prepare('SELECT * FROM events WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;if($edit){$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? ORDER BY id');$b->execute([$editId]);$batches=$b->fetchAll();}}
$unitsStmt=$pdo->prepare('SELECT id,name FROM business_units WHERE tenant_id=? AND status="active" ORDER BY name');$unitsStmt->execute([$tenantId]);$units=$unitsStmt->fetchAll();
$tab=(string)($_GET['tab']??'all');$tabs=['all'=>'Todos','active'=>'Ativos','closed'=>'Encerrados','draft'=>'Rascunhos'];if(!isset($tabs[$tab]))$tab='all';$sql='SELECT e.*,bu.name unit_name,(SELECT COALESCE(SUM(quantity_sold),0) FROM ticket_batches b WHERE b.event_id=e.id) sold,(SELECT COALESCE(SUM(quantity_reserved),0) FROM ticket_batches b WHERE b.event_id=e.id) reserved,(SELECT COUNT(*) FROM tickets t WHERE t.event_id=e.id) tickets_count FROM events e LEFT JOIN business_units bu ON bu.id=e.unit_id WHERE e.tenant_id=?';$args=[$tenantId];if($unitId){$sql.=' AND (e.unit_id IS NULL OR e.unit_id=?)';$args[]=$unitId;}if($tab==='active')$sql.=' AND e.status="published"';elseif($tab==='closed')$sql.=' AND e.status IN ("closed","cancelled")';elseif($tab==='draft')$sql.=' AND e.status="draft"';$sql.=' ORDER BY e.starts_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$events=$s->fetchAll();$editBatchId=(int)($_GET['batch']??0);$editBatch=null;if($editBatchId&&$edit){foreach($batches as$b)if((int)$b['id']===$editBatchId)$editBatch=$b;}
function legacy_event_status(string$s):string{return match($s){'published'=>'Ativo','draft'=>'Rascunho','closed'=>'Encerrado','cancelled'=>'Cancelado',default=>$s};}
