<?php if(!$edit&&!$isNew):?><div class="section-head"><div><h2 style="margin:0">Gerencie os eventos dos seus clientes</h2><p class="muted">Crie eventos, lotes e acompanhe as vendas.</p></div><a class="button primary" href="<?= Security::e(em_url('/?route=events&new=1')) ?>">+ Novo Evento</a></div><nav class="legacy-event-tabs"><?php foreach($tabs as$key=>$label):?><a class="<?= $tab===$key?'active':'' ?>" href="<?= Security::e(em_url('/?route=events&tab='.$key)) ?>"><?= Security::e($label) ?></a><?php endforeach;?></nav><section class="legacy-event-list"><?php foreach($events as$event):?><article class="legacy-event-card"><div class="legacy-event-cover"<?= !empty($event['banner_url'])?' style="background-image:url(\''.Security::e($event['banner_url']).'\')"':'' ?>></div><div class="legacy-event-body"><h3><?= Security::e($event['name']) ?></h3><div class="legacy-event-meta"><span><?= Security::e($event['unit_name']??'Geral') ?></span><span><?= Security::e(date('d/m/Y H:i',strtotime($event['starts_at']))) ?></span><span><?= Security::e($event['venue']??'') ?></span><span>Vendas: <?= (int)$event['sold'] ?></span></div><span class="legacy-event-status <?= Security::e(legacy_event_status_class((string)$event['status'])) ?>"><?= Security::e(legacy_event_status((string)$event['status'])) ?></span></div><div class="legacy-event-actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=events&edit='.(int)$event['id'])) ?>">Editar</a><a class="button secondary" target="_blank" href="<?= Security::e(em_url('/evento.php?empresa='.urlencode($tenantSlug).'&evento='.urlencode($event['slug']))) ?>">Abrir</a><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="duplicate"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><button class="secondary">Duplicar</button></form></div></article><?php endforeach;?><?php if(!$events):?><div class="card"><p class="muted">Nenhum evento nesta categoria.</p></div><?php endif;?></section><?php else:?><div class="section-head"><div><h2 style="margin:0"><?= $edit?'Editar evento':'Criar Novo Evento' ?></h2><p class="muted">Preencha as informações do evento e configure os ingressos.</p></div><a class="button secondary" href="<?= Security::e(em_url('/?route=events')) ?>">Voltar</a></div><div class="legacy-event-editor"><section class="card"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="event-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Título do Evento<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label>Unidade<select name="unit_id"><option value="0">Todas / geral</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected($edit['unit_id']??$unitId,$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['draft'=>'Rascunho','published'=>'Publicado','closed'=>'Encerrado','cancelled'=>'Cancelado']as$value=>$label):?><option value="<?= $value ?>"<?= em_selected($edit['status']??'draft',$value) ?>><?= $label ?></option><?php endforeach;?></select></label><label>Data e Hora<input type="datetime-local" name="starts_at" required value="<?= $edit?Security::e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):'' ?>"></label><label>Fim<input type="datetime-local" name="ends_at" value="<?= $edit&&$edit['ends_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):'' ?>"></label><label class="span-2">Local<input name="venue" value="<?= Security::e($edit['venue']??'') ?>"></label><label class="span-2">Endereço<input name="address" value="<?= Security::e($edit['address']??'') ?>"></label><label class="span-2">Capa / banner URL<input type="url" name="banner_url" value="<?= Security::e($edit['banner_url']??'') ?>"></label><label class="span-2">Descrição<textarea name="description"><?= Security::e($edit['description']??'') ?></textarea></label><label class="span-2">Slug público<input name="slug" value="<?= Security::e($edit['slug']??'') ?>"></label><button class="primary span-2">Salvar Evento</button></form></section><section><?php if($edit):?><div class="card"><div class="section-head"><div><h2>Ingressos</h2><p class="muted">Tipos, valores e quantidades disponíveis.</p></div></div><div class="ticket-batches"><?php foreach($batches as$batch):?><div class="ticket-batch"><strong><?= Security::e($batch['name']) ?></strong><span><?= em_money($batch['price_cents']) ?></span><span><?= (int)$batch['quantity_total'] ?> total</span><span><?= (int)$batch['quantity_sold'] ?> vendidos</span><a class="button secondary" href="<?= Security::e(em_url('/?route=events&edit='.$editId.'&batch='.(int)$batch['id'])) ?>">Editar</a></div><?php endforeach;?></div><hr style="border-color:var(--line);margin:20px 0"><h3><?= $editBatch?'Editar ingresso':'Adicionar Ingresso' ?></h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="batch-save"><input type="hidden" name="event_id" value="<?= (int)$edit['id'] ?>"><input type="hidden" name="id" value="<?= (int)($editBatch['id']??0) ?>"><label>Tipo de Ingresso<input name="name" required value="<?= Security::e($editBatch['name']??'') ?>" placeholder="Pista"></label><label>Valor (R$)<input name="price" inputmode="decimal" required value="<?= $editBatch?Security::e(number_format($editBatch['price_cents']/100,2,',','')):'' ?>"></label><label>Quantidade<input type="number" name="quantity_total" min="1" required value="<?= (int)($editBatch['quantity_total']??1) ?>"></label><label class="checkbox"><input type="checkbox" name="active"<?= em_checked($editBatch?($editBatch['active']??0):1) ?>> Ativo</label><label>Início venda<input type="datetime-local" name="sales_start" value="<?= $editBatch&&$editBatch['sales_start']?Security::e(date('Y-m-d\TH:i',strtotime($editBatch['sales_start']))):'' ?>"></label><label>Fim venda<input type="datetime-local" name="sales_end" value="<?= $editBatch&&$editBatch['sales_end']?Security::e(date('Y-m-d\TH:i',strtotime($editBatch['sales_end']))):'' ?>"></label><button class="secondary span-2"><?= $editBatch?'Salvar ingresso':'+ Adicionar Ingresso' ?></button></form></div><?php else:?><div class="card"><h2>Ingressos</h2><p class="muted">Salve o evento primeiro para adicionar os tipos de ingresso.</p></div><?php endif;?></section></div><?php endif;?>
